//! Where a separated Core lives and how its Gateway finds it (stage 1-C of the
//! Gateway/Core separation, docs/gateway-core-separation-design.md).
//!
//! botd owns the directory; the Gateway only reads from it. Everything here is a naming and
//! permission convention shared by both sides, so they cannot disagree:
//! - `<dir>/core-<slot>.sock`: one Unix socket per Core slot (0600, in a 0700 directory),
//! - `<dir>/core.secret`: the capability secret (0600, 64 hex digits), regenerated by botd
//!   each time it starts Cores, so a secret never outlives the Cores it was made for,
//! - the Core identity is derived, not stored: Bot, Shard and a fixed generation. A later
//!   stage that swaps Cores in place will give each its own generation.

use crate::AppError;
use crate::protocol::{BotId, GenerationId, Identity, OwnershipEpoch, Shard};
use crate::secret_file::{generate_secret_file, load_secret_file};
use crate::worker::{CoreAttach, failure};
use std::os::unix::fs::{MetadataExt, PermissionsExt};
use std::path::{Component, Path, PathBuf};

/// Core processes per Shard (the same pool size the embedded layout uses).
pub const SLOTS: usize = 2;
/// The generation every separated Core of this stage carries.
const GENERATION: u64 = 1;
/// `sun_path` is 108 bytes including the terminator; stay clearly below it.
const MAX_SOCKET_PATH: usize = 100;

pub fn socket_path(dir: &Path, slot: usize) -> PathBuf {
    dir.join(format!("core-{slot}.sock"))
}

pub fn secret_path(dir: &Path) -> PathBuf {
    dir.join("core.secret")
}

/// The identity both a Core (started by botd) and its Gateway present in Hello.
pub fn identity(bot_id: BotId, shard: Shard) -> Identity {
    Identity {
        bot_id,
        shard,
        generation_id: GenerationId(GENERATION),
        ownership_epoch: OwnershipEpoch(0),
    }
}

fn validate_dir(dir: &Path) -> Result<(), AppError> {
    if !dir.is_absolute() || dir.components().any(|part| part == Component::ParentDir) {
        return Err(failure(
            "core directory must be absolute and free of parent components",
        ));
    }
    if socket_path(dir, SLOTS - 1).as_os_str().len() > MAX_SOCKET_PATH {
        return Err(failure("core directory path is too long for a Unix socket"));
    }
    Ok(())
}

/// Creates the directory (0700) if needed and checks it is ours and private.
pub fn prepare_dir(dir: &Path) -> Result<(), AppError> {
    validate_dir(dir)?;
    std::fs::create_dir_all(dir)?;
    std::fs::set_permissions(dir, std::fs::Permissions::from_mode(0o700))?;
    let meta = std::fs::symlink_metadata(dir)?;
    if !meta.is_dir() || meta.mode() & 0o077 != 0 {
        return Err(failure("core directory is not private"));
    }
    Ok(())
}

/// A new secret for a new set of Cores; the old one (if any) is removed first.
pub fn renew_secret(dir: &Path) -> Result<(), AppError> {
    let path = secret_path(dir);
    match std::fs::remove_file(&path) {
        Ok(()) => {}
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
        Err(_) => return Err(failure("cannot replace the core secret")),
    }
    generate_secret_file(&path).map_err(|_| failure("cannot create the core secret"))
}

/// Gateway side: everything `Manager::attach_gateway_pool` needs, from the directory.
pub fn load(dir: &Path, bot_id: BotId, shard: Shard, epoch: u64) -> Result<CoreAttach, AppError> {
    validate_dir(dir)?;
    let secret =
        load_secret_file(&secret_path(dir)).map_err(|_| failure("core secret is unreadable"))?;
    Ok(CoreAttach {
        sockets: (0..SLOTS).map(|slot| socket_path(dir, slot)).collect(),
        secret,
        identity: Identity {
            ownership_epoch: OwnershipEpoch(epoch),
            ..identity(bot_id, shard)
        },
    })
}

/// Removes what a stopped set of Cores leaves behind. Best effort.
pub fn cleanup(dir: &Path) {
    for slot in 0..SLOTS {
        let _ = std::fs::remove_file(socket_path(dir, slot));
    }
    let _ = std::fs::remove_file(secret_path(dir));
}

#[cfg(test)]
mod tests {
    use super::*;

    fn temp(name: &str) -> PathBuf {
        let dir =
            std::env::temp_dir().join(format!("core-attach-unit-{name}-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        dir
    }

    #[test]
    fn directory_is_private_and_secret_is_renewed_not_reused() {
        let dir = temp("renew");
        prepare_dir(&dir).unwrap();
        assert_eq!(
            std::fs::metadata(&dir).unwrap().permissions().mode() & 0o777,
            0o700
        );
        renew_secret(&dir).unwrap();
        let first = std::fs::read(secret_path(&dir)).unwrap();
        renew_secret(&dir).unwrap();
        assert_ne!(first, std::fs::read(secret_path(&dir)).unwrap());
        let shard = Shard::new(0, 1).unwrap();
        let attach = load(&dir, BotId(7), shard, 0).unwrap();
        assert_eq!(attach.sockets.len(), SLOTS);
        assert_eq!(attach.identity, identity(BotId(7), shard));
        cleanup(&dir);
        assert!(!secret_path(&dir).exists());
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn unsafe_or_too_long_directories_are_refused() {
        assert!(prepare_dir(Path::new("relative")).is_err());
        assert!(prepare_dir(Path::new("/tmp/a/../b")).is_err());
        let long = PathBuf::from(format!("/tmp/{}", "x".repeat(120)));
        assert!(prepare_dir(&long).is_err());
    }

    #[test]
    fn a_loose_secret_file_is_not_accepted() {
        let dir = temp("loose");
        prepare_dir(&dir).unwrap();
        renew_secret(&dir).unwrap();
        std::fs::set_permissions(secret_path(&dir), std::fs::Permissions::from_mode(0o644))
            .unwrap();
        assert!(load(&dir, BotId(7), Shard::new(0, 1).unwrap(), 0).is_err());
        let _ = std::fs::remove_dir_all(&dir);
    }
}
